    REJECT_MEMO = #{rej_memo},
    MOD_DT = SYSTIMESTAMP,
    MOD_ID = #{mod_id}
where MSG_TEMPLATE_NO = '${tmplid}'

update ${tmp_table}
set STATUS = '4',
    KAKAO_INS_STATUS = 'INS',
    MOD_DT = SYSTIMESTAMP,
    MOD_ID = #{mod_id}
where MSG_TEMPLATE_NO = '${tmplid}'

update ${tmp_table}
set KAKAO_STATUS = '${tmplstatus}',
    MOD_DT = SYSTIMESTAMP,
    MOD_ID = #{mod_id}
where MSG_TEMPLATE_NO = '${tmplid}'
